/**
 * NORMALIZACIÓN (Run Once for All Items)
 * Input: items desde Google Sheets
 * Output: array de items normalizados -> [{ json: { ... } }, ...]
 */

const items = $input.all();

/* -------- utilidades -------- */
function normalizeKey(key){
  return (key||"")
    .toLowerCase()
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu,"")   // quita acentos
    .replace(/[^a-z0-9_ ]/g,"")
    .replace(/\s+/g,"_");
}
function unaccentLower(s){
  return (s??"").toString().toLowerCase().normalize("NFD").replace(/\p{Diacritic}/gu,"");
}
function yn(v){
  const t = unaccentLower(v).trim();
  return ["si","sí","yes","y"].some(x=>t.startsWith(x)) ? "si" : "no";
}
function parseDate(v){
  if(!v) return null;
  if(typeof v==="string"){
    const s = v.trim();
    // DD/MM/YYYY
    let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
    if(m){ const[,d,mo,y]=m; return new Date(Number(y.length===2?`20${y}`:y), Number(mo)-1, Number(d)); }
    // DD-MM-YYYY (tu Sheet)
    m = s.match(/^(\d{1,2})\-(\d{1,2})\-(\d{2,4})$/);
    if(m){ const[,d,mo,y]=m; return new Date(Number(y.length===2?`20${y}`:y), Number(mo)-1, Number(d)); }
    const t = Date.parse(s);
    if(!Number.isNaN(t)) return new Date(t);
  }
  if (v instanceof Date) return v;
  if (typeof v === "number") return new Date(v);
  return null;
}
function toISODate(d){
  const pad = (n)=>String(n).padStart(2,"0");
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
}
/* -------------------------------- */

const out = items.map((it) => {
  const rec = it.json ?? it; // seguridad
  // Normalizo nombres de columnas
  const m = {};
  for (const k of Object.keys(rec)) m[normalizeKey(k)] = rec[k];

  // Fecha
  const d = parseDate(m.fecha);
  const fecha_iso = d ? toISODate(d) : null;
  const fecha_ts = d ? d.getTime() : null;

  // Puntuación puede venir como "Puntuación " (con espacio final)
  const puntuacionRaw = m.puntuacion ?? m.puntuacion_ ?? rec["Puntuación "] ?? 0;

  return {
    json: {
      row_number: m.row_number ?? null,
      canal: m.canal ?? "",
      fecha: fecha_iso,        // 'YYYY-MM-DD' (estable para filtros)
      fecha_ts,                // timestamp (útil para ordenar)
      agente: m.quien_llama ?? m.quien_llama_ ?? m.agente ?? "",
      id_cliente: m.id_cliente ?? "",
      nombre_completo: m.nombre_completo ?? m.nombre ?? "",
      telefono: m.telefono ?? "",
      email: m.email ?? "",
      id_llamada: m.id_llamada ?? "",
      resultado: yn(m.resultado),
      necesidad: yn(m.necesidad),
      deseo: yn(m.deseo),
      capacidad_financiera: yn(m.capacidad_financiera),
      puntuacion: Number(String(puntuacionRaw).toString().replace(",", ".")) || 0,
      justificacion: m.justificacion ?? "",
      recomendaciones: m.recomendaciones ?? "",
      audio_url: m.id_llamada_twilio ?? m.audio ?? "",
      contacto_url: m.enlace_a_url_contacto ?? "",
      _raw: rec,               // original por si lo necesitas después
    }
  };
});

return out;

/**
 * PROCESAR DATOS (Run Once for All Items)
 * Input: items normalizados
 * Output: Un objeto anidado por Agente.
 * {
 * "meta": { "allAgents": ["Todos", "Agente A", ...], "generatedAt": "..." },
 * "Todos": { "daily": {...}, "weekly": {...}, "rollingMonthly": {...}, "rollingSixtyDay": {...}, "monthly": {...} },
 * "Agente A": { "daily": {...}, ... }
 * }
 */

const items = $input.all(); // cada item = { json: {...} }

// --- Funciones de Fecha ---
function endOfDay(d){ return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999); }
function startOfDay(d){ return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 0, 0, 0, 0); }
function startOfMonth(d){ return new Date(d.getFullYear(), d.getMonth(), 1); }
function formatDate(d){ return d ? d.toLocaleDateString() : ""; }
function toMidnight(d){ return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
// --------------------------

// --- Definición de Rangos ---
const now = new Date();
const todayStart = startOfDay(now);
const todayEnd   = endOfDay(now);
const monthStart = startOfMonth(now);
const monthEnd   = endOfDay(now);
const sevenDaysStart  = startOfDay(new Date(now.getFullYear(), now.getMonth(), now.getDate() - 6));
const thirtyDaysStart = startOfDay(new Date(now.getFullYear(), now.getMonth(), now.getDate() - 29));
// NUEVO RANGO
const sixtyDaysStart  = startOfDay(new Date(now.getFullYear(), now.getMonth(), now.getDate() - 59));
const rollingEnd      = todayEnd;
// --------------------------

// Normaliza input -> fecha y números consistentes
const recs = items
  .map(it => it.json || it)
  .filter(r => r.fecha_ts || r.fecha)
  .map(r => {
    let d = r.fecha_ts ? new Date(Number(r.fecha_ts)) : (r.fecha ? new Date(r.fecha) : null);
    if (d) d = toMidnight(d);
    // IMPORTANTE: Normalizar el nombre del agente aquí
    const agenteNormalizado = r.agente || "(Sin agente)";
    return {
      ...r,
      agente: agenteNormalizado, // Aseguramos que "agente" exista
      _date: d,
      _score: Number(r.puntuacion) || 0,
    };
  })
  .filter(r => r._date);

// --- Función de Agregación Universal (SIN CAMBIOS) ---
function aggregate(rangeStart, rangeEnd, subset) {
  const rows = subset.map(r => ({
    fecha: formatDate(r._date),
    agente: r.agente,
    cliente: r.nombre_completo || "",
    puntuacion: r._score,
    justificacion: r.justificacion || "",
    recomendaciones: r.recomendaciones || "",
    audio_url: r.audio_url || "",
    resultado: r.resultado,
    necesidad: r.necesidad,
    deseo: r.deseo,
    capacidad_financiera: r.capacidad_financiera,
  }));

  const total = subset.length;
  const resultadoSi  = subset.filter(r => r.resultado === 'si').length;
  const necesidadSi  = subset.filter(r => r.necesidad === 'si').length;
  const deseoSi      = subset.filter(r => r.deseo === 'si').length;
  const capacidadSi  = subset.filter(r => r.capacidad_financiera === 'si').length;
  const avgScore     = total ? Number((subset.reduce((a,b)=>a + (b._score||0), 0) / total).toFixed(2)) : 0;
  const qualifiedLeads = subset.filter(r => r.resultado === 'si' && r.capacidad_financiera === 'si').length;

  const scoreBins = { '0-2': 0, '3-5': 0, '6-8': 0, '9-10': 0 };
  for (const r of subset) {
      const s = r._score;
      if (s <= 2) scoreBins['0-2']++;
      else if (s <= 5) scoreBins['3-5']++;
      else if (s <= 8) scoreBins['6-8']++;
      else if (s <= 10) scoreBins['9-10']++;
  }
  const byScore = Object.entries(scoreBins).map(([label, value]) => ({ label, value }));

  const dayMap = new Map();
  for (const r of subset) {
    const key = r._date.toISOString();
    const it = dayMap.get(key) || { date: new Date(r._date), llamadas: 0, suma: 0 };
    it.llamadas += 1;
    it.suma += r._score;
    dayMap.set(key, it);
  }
  const byDay = [...dayMap.values()]
    .sort((a,b)=>a.date - b.date)
    .map(x => ({ date: formatDate(x.date), llamadas: x.llamadas, promedio: Number((x.suma/x.llamadas).toFixed(2)) }));

  const agMap = new Map();
  for (const r of subset) {
    const k = r.agente; // Ya está normalizado
    const it = agMap.get(k) || { agente: k, llamadas: 0, suma: 0 };
    it.llamadas += 1;
    it.suma += r._score;
    agMap.set(k, it);
  }
  const byAgent = [...agMap.values()]
    .map(x => ({ agente: x.agente, llamadas: x.llamadas, promedio: x.llamadas ? Number((x.suma/x.llamadas).toFixed(2)) : 0 }))
    .sort((a,b)=> b.llamadas - a.llamadas);

  const chMap = new Map();
  for (const r of subset) {
    const k = r.canal || "(Sin canal)";
    chMap.set(k, (chMap.get(k) || 0) + 1);
  }
  const byChannel = [...chMap.entries()].map(([canal, value]) => ({ canal, value }));

  return {
    label: rangeStart.toLocaleDateString(undefined, { month: 'long', year: 'numeric' }),
    rangeStart: formatDate(rangeStart),
    rangeEnd: formatDate(rangeEnd),
    kpis: {
      total, avgScore, resultadoSi, necesidadSi, deseoSi, capacidadSi, qualifiedLeads,
      tasaResultado: total ? Number(((resultadoSi / total) * 100).toFixed(1)) : 0,
      tasaNecesidad: total ? Number(((necesidadSi / total) * 100).toFixed(1)) : 0,
      tasaDeseo:     total ? Number(((deseoSi / total) * 100).toFixed(1)) : 0,
      tasaCapacidad:  total ? Number(((capacidadSi / total) * 100).toFixed(1)) : 0,
      tasaQualified:  total ? Number(((qualifiedLeads / total) * 100).toFixed(1)) : 0,
    },
    byDay, byAgent, byChannel, byScore, rows,
  };
}
// ---------------------------------

// --- LÓGICA DE BUCLE POR AGENTE ---

// 1. Obtener lista única de agentes
const allAgents = ['Todos', ...new Set(recs.map(r => r.agente))].sort();

// 2. Preparar el objeto final
const finalData = {
  meta: {
    generatedAt: new Date().toISOString(),
    allAgents: allAgents
  }
};

// 3. Iterar por CADA agente (incluyendo "Todos")
for (const agentName of allAgents) {

  // 3.1. Filtrar los registros base para este agente
  const agentRecs = (agentName === 'Todos')
    ? recs
    : recs.filter(r => r.agente === agentName);

  // 3.2. Crear los subsets de FECHA para ESTE agente
  const monthlySubset = agentRecs.filter(r => r._date >= monthStart && r._date <= monthEnd);
  const dailySubset   = agentRecs.filter(r => r._date >= todayStart && r._date <= todayEnd);
  const weeklySubset = agentRecs.filter(r => r._date >= sevenDaysStart && r._date <= rollingEnd);
  const rollingMonthlySubset = agentRecs.filter(r => r._date >= thirtyDaysStart && r._date <= rollingEnd);
  // NUEVO SUBSET
  const rollingSixtyDaySubset = agentRecs.filter(r => r._date >= sixtyDaysStart && r._date <= rollingEnd);

  // 3.3. Calcular las agregaciones para ESTE agente
  const monthly = aggregate(monthStart, monthEnd, monthlySubset);
  const daily   = aggregate(todayStart, todayEnd, dailySubset);
  const weekly = aggregate(sevenDaysStart, rollingEnd, weeklySubset);
  const rollingMonthly = aggregate(thirtyDaysStart, rollingEnd, rollingMonthlySubset);
  // NUEVA AGREGACIÓN
  const rollingSixtyDay = aggregate(sixtyDaysStart, rollingEnd, rollingSixtyDaySubset);

  // 3.4. Guardar el paquete de datos para ESTE agente
  finalData[agentName] = {
    daily,
    weekly,
    rollingMonthly,
    rollingSixtyDay, // <-- AÑADIDO
    monthly
  };
}

// 4. Devolver la nueva estructura de datos completa
return [{
  json: finalData
}];

