/**
 * HTML (Run Once for All Items) – 4 Tabs con FILTRO GLOBAL y CLICK-TO-FILTER
 * Input : [{ json: { "meta":{...}, "Todos":{...}, "Agente A":{...} } }]
 * Output: [{ json: { html } }]
 */

const input = ($input.first() || {}).json || {};

// NOTA: La función safePack ya no es necesaria aquí si el nodo anterior
// SIEMPRE produce la estructura correcta (lo cual hace).
// La dejaremos por seguridad, pero aplicada dentro del bucle.

function safePack(p = {}) {
  const pack = {
    label: p.label || "",
    rangeStart: p.rangeStart || "",
    rangeEnd: p.rangeEnd || "",
    kpis: {
      total: Number(p?.kpis?.total || 0),
      resultadoSi: Number(p?.kpis?.resultadoSi || 0),
      necesidadSi: Number(p?.kpis?.necesidadSi || 0),
      deseoSi: Number(p?.kpis?.deseoSi || 0),
      capacidadSi: Number(p?.kpis?.capacidadSi || 0),
      avgScore: Number(p?.kpis?.avgScore || 0),
      qualifiedLeads: Number(p?.kpis?.qualifiedLeads || 0),
      tasaQualified: Number(p?.kpis?.tasaQualified || 0),
    },
    byDay: Array.isArray(p.byDay) ? p.byDay : [],
    byAgent: Array.isArray(p.byAgent) ? p.byAgent : [],
    byChannel: Array.isArray(p.byChannel) ? p.byChannel : [],
    byScore: Array.isArray(p.byScore) ? p.byScore : [],
    rows: Array.isArray(p.rows) ? p.rows : [],
  };
  return pack;
}

// Procesamos la nueva estructura de datos
const DATA = {
  meta: input.meta || { allAgents: ['Todos'] }
};
for (const agentKey of (DATA.meta.allAgents || ['Todos'])) {
  if (input[agentKey]) {
    DATA[agentKey] = {
      daily: safePack(input[agentKey].daily),
      weekly: safePack(input[agentKey].weekly),
      rollingMonthly: safePack(input[agentKey].rollingMonthly),
      monthly: safePack(input[agentKey].monthly)
    };
  }
}
// Asegurarnos que "Todos" exista si algo falla
if (!DATA.Todos) {
  DATA.Todos = {
    daily: safePack(), weekly: safePack(), rollingMonthly: safePack(), monthly: safePack()
  };
}


