  <script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script>

  <script>
    const DATA = ${JSON.stringify(DATA)};
    const THEME_BG = '#151515';
    const THEME_TEXT = '#e5e5e5';
    const THEME_GRID = '#2a2a2a';
    const THEME_ACCENT = '#93c5fd';

    // Header y rangos (solo fecha de generación)
    document.getElementById('generatedAt').textContent = new Date(DATA.meta?.generatedAt || Date.now()).toLocaleString();

    function setRanges(prefix, pack) {
      if (document.getElementById(prefix+'_rangeStart')) {
        document.getElementById(prefix+'_rangeStart').textContent = pack.rangeStart || '';
        document.getElementById(prefix+'_rangeEnd').textContent   = pack.rangeEnd   || '';
      }
    }

    function setMainKPIs(prefix, pack) {
      if (document.getElementById(prefix+'_kpi_total')) {
        document.getElementById(prefix+'_kpi_total').textContent = pack.kpis.total || 0;
        document.getElementById(prefix+'_kpi_qualified').textContent = pack.kpis.qualifiedLeads || 0;
        document.getElementById(prefix+'_kpi_tasa_qualified').textContent = (pack.kpis.tasaQualified || 0) + ' %';
      }
    }

    // ------- Plotly helpers (tema oscuro) -------
    const baseLayout = (title='') => ({
      title,
      paper_bgcolor: THEME_BG,
      plot_bgcolor: THEME_BG,
      font: { color: THEME_TEXT },
      margin: {l:40,r:20,t:40,b:40},
      xaxis: { gridcolor: THEME_GRID, zerolinecolor: THEME_GRID },
      yaxis: { gridcolor: THEME_GRID, zerolinecolor: THEME_GRID },
      legend: { orientation: 'h', y: -0.2 },
      hovermode: 'closest'
    });

    const config = { responsive: true, displaylogo: false, modeBarButtonsToRemove: ['select2d','lasso2d'] };

    // ------- FUNCIONES DE PLOTLY (Render) -------
    function renderGauge(containerId, value, total, title) {
      const el = document.getElementById(containerId);
      if (!el) return;
      const layout = { ...baseLayout(), margin: { t: 40, b: 10, l: 30, r: 30 }, height: 180 };
      const data = [{
        type: "indicator", mode: "gauge+number", value: value,
        title: { text: title, font: { size: 16, color: 'var(--muted)' } },
        number: { font: { size: 36, color: 'var(--text)' } },
        gauge: {
          axis: { range: [0, Math.max(1, total)], visible: false, tickwidth: 0 },
          bar: { color: THEME_ACCENT, thickness: 1 },
          bgcolor: THEME_GRID, bordercolor: THEME_GRID, borderwidth: 0
        }
      }];
      Plotly.newPlot(el, data, layout, config);
    }

    function setGauges(prefix, pack){
      const total = pack.kpis.total;
      if (!pack || total === undefined) return;
      renderGauge(prefix+'_gauge_resultado', pack.kpis.resultadoSi, total, 'Resultado "sí"');
      renderGauge(prefix+'_gauge_necesidad', pack.kpis.necesidadSi, total, 'Necesidad "sí"');
      renderGauge(prefix+'_gauge_deseo', pack.kpis.deseoSi, total, 'Deseo "sí"');
      renderGauge(prefix+'_gauge_capacidad', pack.kpis.capacidadSi, total, 'Capacidad "sí"');
    }

    function renderScoreDist(containerId, pack){
      const el = document.getElementById(containerId);
      if (!el || !pack.byScore) return;
      const labels = pack.byScore.map(d => d.label);
      const values = pack.byScore.map(d => d.value);
      Plotly.newPlot(el, [{
        x: labels, y: values, type: 'bar', name: 'Nº Llamadas',
        marker: { color: THEME_ACCENT }
      }], baseLayout(), config);
    }

    function renderLine(containerId, pack){
      const el = document.getElementById(containerId);
      if (!el || !pack.byDay) return;
      const dates = pack.byDay.map(d=>d.date);
      const llamadas = pack.byDay.map(d=>d.llamadas);
      const prom = pack.byDay.map(d=>d.promedio);
      const tr1 = { x: dates, y: llamadas, type: 'scatter', mode: 'lines+markers', name: 'Llamadas', marker: { color: THEME_ACCENT } };
      const tr2 = { x: dates, y: prom, type: 'scatter', mode: 'lines+markers', name: 'Promedio', yaxis: 'y2', marker: { color: '#f59e0b' } };
      const layout = {
        ...baseLayout(),
        yaxis: { title: 'Llamadas', gridcolor: THEME_GRID, zerolinecolor: THEME_GRID },
        yaxis2: { title: 'Promedio', overlaying: 'y', side: 'right', gridcolor: THEME_GRID, zerolinecolor: THEME_GRID, range: [0, 10] }
      };
      Plotly.newPlot(el, [tr1, tr2], layout, config);
    }

    // --- MEJORA 3: Click-to-Filter ---
    // La función ahora acepta 'prefix' para saber qué tabla filtrar
    function renderBars(containerCalls, containerAvg, pack, prefix){
      const elCalls = document.getElementById(containerCalls);
      const elAvg = document.getElementById(containerAvg);
      if (!elCalls || !elAvg || !pack.byAgent) return;

      const labels = pack.byAgent.map(d=>d.agente);
      const calls = pack.byAgent.map(d=>d.llamadas);
      const avg = pack.byAgent.map(d=>d.promedio);

      Plotly.newPlot(elCalls, [{\
        x: labels, y: calls, type: 'bar', name: 'Llamadas', marker: { color: THEME_ACCENT }
      }], baseLayout(), config);

      Plotly.newPlot(elAvg, [{\
        x: labels, y: avg, type: 'bar', name: 'Promedio', marker: { color: '#f59e0b' }
      }], { ...baseLayout(), yaxis: { range: [0, 10], gridcolor:THEME_GRID } }, config);

      // AÑADIDO: Event listener para el clic en el gráfico de barras
      elCalls.on('plotly_click', (data) => {
        if (data.points && data.points.length > 0) {
          const agentName = data.points[0].x; // Obtener el agente de la barra
          // Aplicar el filtro a la tabla correspondiente
          if (tableControllers[prefix]) {
            tableControllers[prefix].filter(agentName);
            // Opcional: actualizar también el input de búsqueda
            document.getElementById('search').value = agentName;
          }
        }
      });
    }

    // ------- Tablas + paginación + búsqueda (Sin cambios, pero crucial) -------

    const tableControllers = {}; // Almacén para los 4 controladores de tabla
    const $search = document.getElementById('search');

    function TableCtl(prefix, rows){
      const pageSize = 10;
      let page = 1;
      let allRows = rows.slice();
      let filtered = rows.slice();
      const $tbody = document.querySelector('#'+prefix+'_tbl tbody'); 
      if (!$tbody) { console.error('No tbody found for '+prefix); return; }

      function render(){
        const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
        if(page > pageCount) page = Math.max(1, pageCount);
        const slice = filtered.slice((page-1)*pageSize, page*pageSize);

        $tbody.innerHTML = slice.map(r => \`
          <tr>
            <td>\${r.fecha||''}</td>
            <td>\${r.agente||'—'}</td>
            <td>\${r.cliente||'—'}</td>
            <td>\${r.puntuacion??''}</td>
            <td style="white-space:pre-wrap;max-width:420px">\${(r.justificacion||'').replace(/</g,'&lt;')}</td>
            <td style="white-space:pre-wrap;max-width:420px">\${(r.recomendaciones||'').replace(/</g,'&lt;')}</td>
            <td>\${r.audio_url?'<a href="'+r.audio_url+'" target="_blank" rel="noreferrer">Escuchar</a>':'—'}</td>
          </tr>
        \`).join('');

        document.getElementById(prefix+'_pageInfo').textContent = \`
          Página \${page} de \${pageCount} — \${filtered.length} resultados
        \`;
        document.getElementById(prefix+'_prev').disabled = page<=1;
        document.getElementById(prefix+'_next').disabled = page>=pageCount;
      }

      function filter(searchTerm) {
        filtered = !searchTerm
          ? allRows.slice()
          : allRows.filter(r => \`
              \${r.agente} \${r.cliente} \${r.justificacion} \${r.recomendaciones}
            \`.toLowerCase().includes(searchTerm.toLowerCase()));
        page = 1;
        render();
      }

      document.getElementById(prefix+'_prev').addEventListener('click', ()=>{page=Math.max(1,page-1);render();});
      document.getElementById(prefix+'_next').addEventListener('click', ()=>{page=page+1;render();});

      // Exponer el controlador
      tableControllers[prefix] = { filter, render, allRows };

      render();
    }

    // ------- NUEVA LÓGICA DE RENDERIZADO (MEJORA 1) -------

    // 1. Función "renderAll" que renderiza UN panel (d, w, rm, m)
    //    con los datos de un paquete específico.
    function renderAll(prefix, dataPack) {
      setRanges(prefix, dataPack); // Pone fechas de rango
      setMainKPIs(prefix, dataPack); // Pone KPIs grandes
      setGauges(prefix, dataPack);   // Dibuja los 4 medidores
      renderLine(prefix+'_line', dataPack); // Dibuja línea de tiempo
      // IMPORTANTE: Pasamos el 'prefix' a renderBars
      renderBars(prefix+'_bar_calls', prefix+'_bar_avg', dataPack, prefix); 
      renderScoreDist(prefix+'_pie', dataPack); // Dibuja histograma
      TableCtl(prefix, dataPack.rows); // Crea la tabla
    }

    // 2. Función "maestra" que decide QUÉ datos usar
    //    y llama a renderAll para cada panel.
    function renderDashboardForAgent(agentKey) {
      // Limpiar búsqueda al cambiar de agente
      $search.value = ''; 

      // Obtener el paquete de datos del agente (ej. DATA["Agente A"] o DATA["Todos"])
      const agentData = DATA[agentKey];
      if (!agentData) {
        console.error('No hay datos para el agente: ' + agentKey);
        return;
      }

      // Renderizar los 4 paneles con los datos de ESE agente
      renderAll('d', agentData.daily);
      renderAll('w', agentData.weekly);
      renderAll('rm', agentData.rollingMonthly);
      renderAll('m', agentData.monthly);
    }

    // 3. Función para poblar el dropdown de agentes
    function populateAgentFilter() {
      const $select = document.getElementById('agentFilter');
      if (!$select || !DATA.meta || !DATA.meta.allAgents) return;

      $select.innerHTML = DATA.meta.allAgents
        .map(agentName => \`<option value="\${agentName}">\${agentName}</option>\`)
        .join('');
    }

    // --- Lógica de Pestañas (Tabs) ---
    // (Movida antes de los listeners de filtro)
    document.querySelectorAll('.tab').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.tab').forEach(b => b.classList.remove('active'));
        document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
        btn.classList.add('active');
        const sel = btn.getAttribute('data-target');
        document.querySelector(sel).classList.add('active');

        setTimeout(()=>window.dispatchEvent(new Event('resize')), 0);

        // Al cambiar de tab, aplicar filtro de búsqueda actual a la tabla de esa tab
        const s = $search.value.trim().toLowerCase();
        let prefix = sel.replace('#panel-', '').substring(0, 2); // 'da'->'d', 'we'->'w', 'ro'->'rm', 'mo'->'m'
        if (prefix === 'ro') prefix = 'rm';
        if (prefix === 'da') prefix = 'd';

        if (prefix && tableControllers[prefix]) {
          tableControllers[prefix].filter(s);
        }
      });
    });

    // --- Listeners de Filtros ---

    // Listener para el input de búsqueda (filtra solo la tabla activa)
    $search.addEventListener('input', (e) => {
      const s = e.target.value.trim().toLowerCase();
      const activeTab = document.querySelector('.tab.active');
      if (!activeTab) return;

      const targetPanelId = activeTab.getAttribute('data-target');
      let prefix = targetPanelId.replace('#panel-', '').substring(0, 2);
      if (prefix === 'ro') prefix = 'rm';
      if (prefix === 'da') prefix = 'd';

      if (prefix && tableControllers[prefix]) {
        tableControllers[prefix].filter(s);
      }
    });

    // Listener para el dropdown de Agente (RE-RENDERIZA TODO)
    document.getElementById('agentFilter').addEventListener('change', (e) => {
      renderDashboardForAgent(e.target.value);
    });

